html:
{% set template = frappe.get_doc("Proposal Template", doc.proposal_template) %}
{% macro render_section(key, default_label, content) %}
  {% set matches = template.sections | selectattr("section_key", "equalto", key) | list %}
  {% set row = matches[0] if matches else none %}
  {% if row and row.is_included and content %}
    <div class="proposal-section">
      <h3>{{ row.section_label or default_label }}</h3>
      <div>{{ content }}</div>
    </div>
  {% endif %}
{% endmacro %}

<style>
  .proposal-header { margin-bottom: 24px; }
  .proposal-header h1 { margin-bottom: 4px; }
  .proposal-meta { color: #666; font-size: 11px; }
  .proposal-section { margin-bottom: 20px; }
  .proposal-section h3 { border-bottom: 1px solid #ccc; padding-bottom: 4px; }
</style>

{% if letter_head and not no_letterhead -%}
  <div class="letter-head">{{ letter_head }}</div>
  <hr>
{%- endif %}

<div class="proposal-header">
  <h1>{{ doc.title or doc.name }}</h1>
  <div class="proposal-meta">
    {{ doc.bid }} &middot; Version {{ doc.version }} &middot; {{ doc.status }}
  </div>
</div>

{{ render_section("executive_summary", "Executive Summary", doc.executive_summary) }}
{{ render_section("technical_approach", "Technical Approach", doc.technical_approach) }}
{{ render_section("commercial_terms", "Commercial Terms", doc.commercial_terms) }}
{{ render_section("compliance_statement", "Compliance Statement", doc.compliance_statement) }}
